                try:
                    xml_content = z.read(f'ppt/slides/slide{i}.xml').decode('utf-8')
                    text += re.sub('<[^>]+>', ' ', xml_content) + " "
                except KeyError:
                    # Slide doesn't exist, we reached the end or skipped
                    if i > 1: # if we found at least one, and now missing, likely end
                         break
                    pass
    except Exception as e:
        print(f"Error reading PPTX {filepath}: {e}")
